function Payroll({profile}:{profile:Profile}){
  const [periods,setPeriods]=useState<any[]>([]),[message,setMessage]=useState(''),[busy,setBusy]=useState('')
  const canManage=['owner','hr_admin','finance'].includes(profile.role)
  const load=()=>supabase.from('payroll_periods').select('*').order('period_end',{ascending:false}).then(({data})=>setPeriods(data||[]))
  useEffect(()=>{void load()},[])
  const create=async()=>{
    const n=new Date(),start=new Date(n.getFullYear(),n.getMonth(),1).toISOString().slice(0,10),end=new Date(n.getFullYear(),n.getMonth()+1,0).toISOString().slice(0,10)
    if(periods.some(x=>x.period_start===start)){setMessage('Payroll bulan ini sudah dibuat.');return}
    setBusy('create')
    const [{data:emps},{data:compensations}]=await Promise.all([supabase.from('employees').select('*').eq('is_active',true),supabase.from('employee_compensation').select('amount,employee_id,payroll_components(name,kind)').eq('is_recurring',true)])
    const entries=(emps||[]).map((employee:any)=>{const details=(compensations||[]).filter((item:any)=>item.employee_id===employee.id).map((item:any)=>({name:item.payroll_components?.name||'Komponen',kind:item.payroll_components?.kind||'earning',amount:Number(item.amount)}));const earnings=details.filter((x:any)=>x.kind==='earning').reduce((sum:number,x:any)=>sum+x.amount,0),deductions=details.filter((x:any)=>x.kind==='deduction').reduce((sum:number,x:any)=>sum+x.amount,0),base=Number(employee.base_salary||0);return {company_id:profile.company_id,employee_id:employee.id,base_salary:base,earnings,deductions,net_pay:base+earnings-deductions,detail:details}})
    const totalGross=entries.reduce((sum:number,x:any)=>sum+x.base_salary+x.earnings,0),totalDeduction=entries.reduce((sum:number,x:any)=>sum+x.deductions,0),totalNet=entries.reduce((sum:number,x:any)=>sum+x.net_pay,0)
    const {data:period,error}=await supabase.from('payroll_periods').insert({company_id:profile.company_id,period_start:start,period_end:end,payment_date:end,total_gross:totalGross,total_deduction:totalDeduction,total_net:totalNet}).select('*').single()
    if(error||!period){setBusy('');setMessage('Payroll belum dapat dibuat.');return}
    if(entries.length){const {error:entryError}=await supabase.from('payroll_entries').insert(entries.map(({company_id,employee_id,base_salary,earnings,deductions,net_pay,detail}:any)=>({company_id,payroll_period_id:period.id,employee_id,base_salary,earnings,deductions,net_pay,detail})));if(entryError){setMessage('Draft dibuat, tetapi rincian karyawan belum tersimpan.')}}
    setBusy('');setMessage('Draft payroll dibuat dari gaji pokok serta komponen tetap karyawan.');void load()
  }
  const move=async(period:any,next:'review'|'approved'|'locked'|'paid')=>{setBusy(period.id);const now=new Date().toISOString(),payload:any={status:next};if(next==='approved'){payload.approved_by=profile.id;payload.approved_at=now}if(next==='locked')payload.locked_at=now;const {error}=await supabase.from('payroll_periods').update(payload).eq('id',period.id);setBusy('');setMessage(error?'Status payroll belum dapat diperbarui.':`Payroll berhasil ${next==='review'?'diajukan untuk review':next==='approved'?'disetujui':next==='locked'?'dikunci':'ditandai sudah dibayar'}.`);if(!error)void load()}
  const nextAction=(p:any)=>p.status==='draft'?['review','Ajukan review']:p.status==='review'?['approved','Setujui']:p.status==='approved'?['locked','Kunci payroll']:p.status==='locked'?['paid','Tandai dibayar']:null
  return <section className="page"><Intro eyebrow="Penggajian" title="Payroll" text="Buat draft dari gaji pokok dan komponen tetap, review, setujui, kunci, lalu tandai dibayar." action={canManage?<button className="button primary" disabled={busy==='create'} onClick={()=>void create()}><Plus/>{busy==='create'?'Membuat draft…':'Buat payroll bulan ini'}</button>:undefined}/>{message&&<p className="note">{message}</p>}<div className="card table"><table><thead><tr><th>Periode</th><th>Tanggal bayar</th><th>Total bersih</th><th>Status</th><th>Aksi</th></tr></thead><tbody>{periods.map(p=>{const action=nextAction(p);return <tr key={p.id}><td><b>{new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(`${p.period_start}T00:00:00`))}</b><small>{p.period_start} s.d. {p.period_end}</small></td><td>{p.payment_date||'—'}</td><td>{money(Number(p.total_net))}<small>Bruto {money(Number(p.total_gross))} · Potongan {money(Number(p.total_deduction))}</small></td><td><span className={`badge ${p.status==='paid'||p.status==='locked'?'active':'draft'}`}>{p.status}</span></td><td>{canManage&&action?<button className="button secondary" disabled={busy===p.id} onClick={()=>void move(p,action[0] as 'review'|'approved'|'locked'|'paid')}>{action[1]}</button>:<span>—</span>}</td></tr>})}</tbody></table>{!periods.length&&<Empty text="Belum ada payroll. Mulai dengan membuat draft periode bulan ini."/>}</div><div className="notice"><ShieldCheck/><div><b>Payroll dibekukan setelah dikunci</b><p>Alur draft → review → disetujui → dikunci → dibayar tercatat pada periode yang sama.</p></div></div></section>}

function Team({profile}:{profile:Profile}){const [rows,setRows]=useState<Profile[]>([]),[open,setOpen]=useState(false),[message,setMessage]=useState('');const load=()=>supabase.from('profiles').select('*').order('created_at').then(({data})=>setRows((data||[])as Profile[]));useEffect(()=>{void load()},[]);const add=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const {data,error}=await supabase.functions.invoke('create-team-member',{body:Object.fromEntries(new FormData(e.currentTarget).entries())});if(error||data?.error)setMessage(data?.error||'Akun tim belum dapat dibuat.');else{setMessage('Akun tim berhasil dibuat dan langsung masuk ke workspace ini.');setOpen(false);void load()}};return <section className="page"><Intro eyebrow="Akses perusahaan" title="Tim" text="Semua anggota masuk ke perusahaan Owner yang sama." action={profile.role==='owner'?<button className="button primary" onClick={()=>setOpen(true)}><Plus/>Tambah tim</button>:undefined}/>{message&&<p className="note">{message}</p>}<div className="team">{rows.map(r=><article className="card member" key={r.id}><div className="avatar">{r.full_name[0]}</div><div><h3>{r.full_name}</h3><p>@{r.username}</p><span className="badge">{roles[r.role]}</span></div></article>)}</div>{open&&<Modal title="Tambah anggota tim" close={()=>setOpen(false)}><form onSubmit={add} className="form"><div className="two"><Field label="Nama lengkap"><input name="fullName" required/></Field><Field label="Jabatan"><input name="jobTitle"/></Field></div><div className="two"><Field label="Username"><input name="username" minLength={4} required/></Field><Field label="Password awal"><input name="password" type="password" minLength={8} required/></Field></div><Field label="Role"><select name="role"><option value="hr_admin">HR / Admin</option><option value="finance">Keuangan</option><option value="supervisor">Atasan</option><option value="employee">Karyawan</option></select></Field><button className="button primary">Buat akun tim</button></form></Modal>}</section>}
function Reports(){const download=async()=>{const {data}=await supabase.from('employees').select('employee_code,full_name,department,position,base_salary,is_active').order('full_name');const header='Kode,Nama,Divisi,Jabatan,Gaji Pokok,Status',lines=(data||[]).map((r:any)=>[r.employee_code,r.full_name,r.department||'',r.position||'',r.base_salary,r.is_active?'Aktif':'Nonaktif'].map(v=>`"${String(v).replaceAll('"','""')}"`).join(','));const blob=new Blob([[header,...lines].join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='data-karyawan.csv';a.click();URL.revokeObjectURL(a.href)};return <section className="page"><Intro eyebrow="Rekap dan ekspor" title="Laporan" text="Unduh data yang dibutuhkan Owner, HR, dan Keuangan."/><div className="reports"><article className="card"><FileText/><h3>Data karyawan</h3><p>Daftar aktif, jabatan, divisi, dan gaji pokok.</p><button className="button secondary" onClick={download}>Unduh CSV</button></article><article className="card"><CircleDollarSign/><h3>Payroll bulanan</h3><p>Ringkasan periode dan total gaji.</p><button className="button secondary" disabled>Segera tersedia</button></article><article className="card"><CalendarCheck/><h3>Presensi</h3><p>Rekap kehadiran dan keterlambatan.</p><button className="button secondary" disabled>Segera tersedia</button></article></div></section>}
function SettingsPage({profile}:{profile:Profile}){const [company,setCompany]=useState<any>(null);useEffect(()=>{supabase.from('companies').select('*').eq('id',profile.company_id).single().then(({data})=>setCompany(data))},[profile.company_id]);return <section className="page"><Intro eyebrow="Konfigurasi" title="Pengaturan perusahaan" text="Identitas usaha dan dasar periode payroll."/><div className="cols"><article className="card"><h3>Perusahaan</h3><dl><dt>Nama workspace</dt><dd>{company?.name||'Memuat…'}</dd><dt>Hari payroll</dt><dd>Tanggal {company?.payroll_day||25} setiap bulan</dd><dt>Zona waktu</dt><dd>{company?.timezone||'Asia/Jakarta'}</dd></dl></article><article className="card"><h3>Keamanan data</h3><p>Data perusahaan dipisahkan dan role diperiksa langsung di database.</p><div className="check"><ShieldCheck/>RLS aktif untuk seluruh tabel payroll</div><div className="check"><ClipboardCheck/>Audit log disiapkan untuk tindakan penting</div></article></div></section>}
function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="modal-layer"><button className="backdrop" onClick={close}/><section className="modal"><header><h3>{title}</h3><button className="icon" onClick={close}><X/></button></header>{children}</section></div>}
